insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Solve step by step. At the very end write: The answer is <<EXPR>> where EXPR is a complete arithmetic formula using ALL relevant variables from the problem combined with operators +, -, *, /, (, ) and integer literals. The formula must include multiple variables - never write just a single number or single variable. Example: The answer is <<n * price - discount + tax>>. No LaTeX, no {}, no **, no backslashes.");

